-- Ключі відповідей до ігор (генерується: _Інструменти/game_keys.js — руками не правити)
-- Читає лише вчитель (authenticated). Учні (anon) доступу не мають.
create table if not exists public.game_keys (
  slug       text primary key references public.games(slug) on delete cascade,
  data       jsonb not null,
  updated_at timestamptz not null default now()
);
alter table public.game_keys enable row level security;
revoke all on public.game_keys from anon;
drop policy if exists game_keys_read on public.game_keys;
create policy game_keys_read on public.game_keys for select to authenticated using (true);

insert into public.game_keys(slug, data, updated_at)
select 'alhorytmy-8', '{"slug":"alhorytmy-8","title":"Алгоритми та програми: розгалуження й логіка — гра для 8 класу","max":26,"stars":26,"rounds":[{"n":1,"type":"sort","task":"Яка форма розгалуження потрібна для цієї задачі? 🔀","hint":"Спершу торкнись <b>картки</b>, потім форми. Питання одне: <b>скільки різних варіантів</b> має результат?","folders":["if — коротка","if…else — повна","if…elif…else"],"stars":[1,6],"items":[{"n":"Решта від’ємна — попередити. Інакше не робити нічого","f":"if — коротка","why":""},{"n":"Поле порожнє — повідомити й вийти з обробника","f":"if — коротка","why":""},{"n":"Вистачило грошей — зелений напис, не вистачило — червоний","f":"if…else — повна","why":""},{"n":"Трикутник існує або не існує","f":"if…else — повна","why":""},{"n":"Бал → рівень: високий, достатній, середній, початковий","f":"if…elif…else","why":""},{"n":"Вік → квиток: безкоштовний, дитячий, повний, пільговий","f":"if…elif…else","why":""}]},{"n":2,"type":"sort","task":"Яку логічну операцію потрібно поставити в умову? 🧩","hint":"Правило з уроку 23: <b>дві окремі ділянки — or</b>, <b>один проміжок — and</b>. І перевірка: прочитай умову вголос як речення про <b>одне</b> число.","folders":["or — диз’юнкція","and — кон’юнкція"],"stars":[7,12],"items":[{"n":"Бал неприпустимий: менший за 1 <b>або</b> більший за 12","f":"or — диз’юнкція","why":""},{"n":"Температура небезпечна: нижче −20 <b>або</b> вище +35","f":"or — диз’юнкція","why":""},{"n":"Хоч одне з трьох полів залишили порожнім","f":"or — диз’юнкція","why":""},{"n":"Вода підходить для купання: від 20 до 28 °C","f":"and — кон’юнкція","why":""},{"n":"Трикутник існує: кожна сторона менша за суму двох інших","f":"and — кон’юнкція","why":""},{"n":"Пароль підходить за довжиною: від 8 до 20 символів","f":"and — кон’юнкція","why":""}]},{"n":3,"type":"num","task":"Порахуй і впиши число 🧮","hint":"Чотири задачі одна за одною. Дробові пиши через <b>кому або точку</b> — приймається і так, і так. Мінус — звичайний.","items":[{"star":13,"q":"Проєкт рахує так: <code>if x < -3 or x > 5: y = 2*x - 12</code>, а <code>else: y = 7 - 8*x</code>.<br>Уводимо <b>x = −3</b>. Яке <b>y</b> покаже проєкт?","a":31,"u":"","calc":"−3 <b>не менше</b> за −3, тому працює друга формула.","tip":"Уважно: чи істинна умова <code>x < -3</code> при x = −3? Межа належить <b>другій</b> гілці.","trap":""},{"star":14,"q":"Мама дала Марійці <b>200 грн</b>. Треба купити <b>400 г</b> печива (кілограм — <b>150 грн</b>), <b>2</b> пакети молока по <b>32 грн</b> і хліб за <b>25 грн</b>.<br>Скільки <b>решти</b> залишиться?","a":51,"u":"грн","calc":"0,4·150 + 2·32 + 25 = 149. Решта — 51 грн.","tip":"400 г — це <b>0,4</b> кілограма, а не 400. Порахуй витрати окремо, потім відніми.","trap":""},{"star":15,"q":"У проєкті <code>elif</code>-ланцюжок із <b>чотирьох</b> гілок: 10–12, 7–9, 4–6, 1–3.<br>Скільки тестових наборів потрібно, щоб перевірити <b>кожну гілку</b> й <b>кожну межу</b>?","a":7,"u":"наборів","calc":"Чотири гілки плюс три межі: 12, 10, 9, 7, 5, 3, 1.","tip":"Порахуй: по одному на кожну гілку — це чотири. А тепер додай набори <b>на межах</b> між гілками.","trap":""},{"star":16,"q":"Депозит: <b>7 %</b> прибутку за <b>пів року</b>, і прибуток <b>додається до вкладу</b>.<br>Поклали <b>1000 грн</b>. Скільки грошей буде на рахунку <b>через рік</b>?","a":1144.9,"u":"грн","calc":"1000·1,07·1,07 = 1144,9. Це 14,49 %, а не 14 %.","tip":"За рік нарахують <b>двічі</b>, і другий раз — уже на збільшену суму. Множники <b>перемножуються</b>.","trap":""}]},{"n":4,"type":"sort","task":"Тут варто написати проєкт — чи швидше без програми? 🤔","hint":"Програму варто писати, коли обчислення <b>повторюється багато разів</b>, дані <b>змінюються</b>, а формула — <b>та сама</b>. Один раз порахувати швидше руками.","folders":["Варто написати проєкт","Швидше без програми"],"stars":[17,22],"items":[{"n":"Щомісяця рахувати оплату за електроенергію для 30 квартир","f":"Варто написати проєкт","why":""},{"n":"Після кожної роботи рахувати відсоток виконаного для всього класу","f":"Варто написати проєкт","why":""},{"n":"Перевірити 40 наборів із зошита: чи існує трикутник","f":"Варто написати проєкт","why":""},{"n":"Один раз перевести 5 кілограмів у грами","f":"Швидше без програми","why":""},{"n":"Порахувати площу однієї кімнати, щоб купити лінолеум","f":"Швидше без програми","why":""},{"n":"Скласти список покупок на вечерю","f":"Швидше без програми","why":""}]},{"n":5,"type":"pick","task":"Познач ЧОТИРИ правильні твердження про логіку в пошуку й фільтрах 🔍","hint":"Останній раунд. Правильних — <b>чотири</b>. Три інші звучать переконливо, але <b>неправильні</b>.","stars":[23,26],"items":[{"n":"Галочки в межах ОДНОГО фільтра з’єднані через or — результатів стає більше","ok":true,"why":""},{"n":"РІЗНІ фільтри з’єднані через and — результатів стає менше","ok":true,"why":""},{"n":"«Нічого не знайдено» найчастіше значить, що умова занадто сувора","ok":true,"why":""},{"n":"У пошуку OR потрібно писати ВЕЛИКИМИ літерами","ok":true,"why":""},{"n":"Чим більше галочок поставиш, тим більше знайдеш","ok":false,"why":"⚠️ залежить, <b>де</b> галочка: у межах одного фільтра — більше, а <b>новий</b> фільтр — менше"},{"n":"Мінус перед словом у пошуку розширює пошук","ok":false,"why":"навпаки: <code>-слово</code> — це <b>not</b>, воно <b>виключає</b> сторінки з цим словом"},{"n":"Галочка «Запам’ятати мене» на чужому комп’ютері безпечна, якщо закрити вкладку","ok":false,"why":"⚠️ ні: ця логічна змінна лишається <b>True</b> і <b>після тебе</b> — разом із доступом до акаунта"}]}]}'::jsonb, now()
