select 'bezpeka-tehnika-8', '{"slug":"bezpeka-tehnika-8","title":"Безпека й технології: рішення, а не вгадування — гра для 8 класу","max":24,"stars":24,"rounds":[{"n":1,"type":"pick","task":"Реклама: «Ваш ПК на 60 % повільніше! Знайдено 1247 помилок! Прискоримо у 5 разів! Залишилось 2 хвилини». Познач ЧОТИРИ ознаки обману 🔎","hint":"Правильних — <b>чотири</b>. Решта три — нормальні речі, а не обман. Читай уважно.","stars":[1,4],"items":[{"n":"«Просканували ваш ПК» — ще до встановлення","ok":true,"why":""},{"n":"Точне число «1247 помилок» без перевірки","ok":true,"why":""},{"n":"Обіцянка «прискорити у 5 разів»","ok":true,"why":""},{"n":"Таймер «залишилось 2 хвилини»","ok":true,"why":""},{"n":"Програма має офіційний сайт з описом","ok":false,"why":"це якраз <b>ознака нормальної</b> програми: ми самі шукаємо офіційний сайт"},{"n":"Програма показує модель процесора й температуру","ok":false,"why":"це робить справжня діагностика, наприклад CPU-Z. Нічого поганого"},{"n":"Windows сам пропонує «Засіб усунення неполадок»","ok":false,"why":"це <b>вбудований</b> інструмент Windows, безкоштовний і безпечний"}]},{"n":2,"type":"sort","task":"Який тип комп’ютера потрібен для цієї задачі? 🖥","hint":"Спершу торкнись <b>картки</b> із задачею, потім — типу комп’ютера. Питання не «що потужніше», а <b>що потрібно</b>.","folders":["Суперкомп’ютер","Сервер","Персональний","Вбудований"],"stars":[5,10],"items":[{"n":"Прогноз погоди на кілька тижнів","f":"Суперкомп’ютер","why":""},{"n":"Модель термоядерного синтезу","f":"Суперкомп’ютер","why":""},{"n":"Шкільний доступ до інтернету","f":"Сервер","why":""},{"n":"Пошта для тисяч користувачів","f":"Сервер","why":""},{"n":"Реферат і презентація для школи","f":"Персональний","why":""},{"n":"Пральна машина обирає режим прання","f":"Вбудований","why":""}]},{"n":3,"type":"pick","task":"Познач ЧОТИРИ речі, які робити МОЖНА ✅","hint":"Правильних — <b>чотири</b>. Три інші — те, чого робити не можна, навіть якщо технічно виходить.","stars":[11,14],"items":[{"n":"Сфотографувати умову задачі й розпізнати текст (OCR)","ok":true,"why":""},{"n":"Перевірити замочок https:// перед уведенням пароля","ok":true,"why":""},{"n":"Зробити резервну копію своїх файлів на інший носій","ok":true,"why":""},{"n":"Написати вчителю, що не розумієш завдання","ok":true,"why":""},{"n":"Прочитати переписку однокласника, якщо телефон відкритий","ok":false,"why":"уміти щось технічно — <b>не те саме</b>, що мати на це право. Це чуже"},{"n":"Відкрити архів із паролем від незнайомця","ok":false,"why":"пароль в архіві ставлять, щоб антивірус не зазирнув усередину"},{"n":"Скопіювати чужий код і здати як свій","ok":false,"why":"списаний код видно одразу, і він нічому не вчить. Краще спитати"}]},{"n":4,"type":"sort","task":"Що робити в цій ситуації? 🔧","hint":"Три варіанти дій: зробити <b>сам за хвилину</b> · запустити <b>засіб Windows</b> · звернутися <b>до фахівця</b>.","folders":["Сам за хвилину","Засіб Windows","До фахівця"],"stars":[15,20],"items":[{"n":"При вмиканні щось написав і не завантажується","f":"Сам за хвилину","why":""},{"n":"Диск заповнений майже повністю","f":"Сам за хвилину","why":""},{"n":"Не працює Wi-Fi","f":"Засіб Windows","why":""},{"n":"Не друкує принтер","f":"Засіб Windows","why":""},{"n":"Засіб Windows не зміг виправити","f":"До фахівця","why":""},{"n":"Критична помилка POST, кабелі перевірено","f":"До фахівця","why":""}]},{"n":5,"type":"pick","task":"Познач ЧОТИРИ речі, які справді можна зробити за програмою «Держава у смартфоні» 📱","hint":"Останній раунд. Правильних — <b>чотири</b>.","stars":[21,24],"items":[{"n":"Відкрити банківський рахунок","ok":true,"why":""},{"n":"Сплатити за комунальні послуги","ok":true,"why":""},{"n":"Надіслати звіт із електронним підписом","ok":true,"why":""},{"n":"Подивитися реєстр земельних ресурсів","ok":true,"why":""},{"n":"Отримати шкільну оцінку без контрольної","ok":false,"why":"це не державна послуга 🙂 Оцінку дає робота, а не застосунок"},{"n":"Змінити закон","ok":false,"why":"закони ухвалює Верховна Рада, а не застосунок"},{"n":"Отримати ПАПЕРОВИЙ гарантійний талон поштою","ok":false,"why":"навпаки: сенс програми в тому, що талон <b>електронний</b>"}]}]}'::jsonb, now()
