select 'dani-ta-informatsiya', '{"slug":"dani-ta-informatsiya","title":"Дані та інформація — гра для 5 класу","max":21,"stars":21,"rounds":[{"n":1,"task":"Який це вид повідомлення? 📨","hint":"Розклади повідомлення за <b>способом подання</b>: спершу торкнись картки, потім — потрібної папки.","type":"sort","folders":["Текстове","Графічне","Звукове"],"items":[{"n":"лист другу","f":"Текстове","why":""},{"n":"новина в газеті","f":"Текстове","why":""},{"n":"фотографія","f":"Графічне","why":""},{"n":"малюнок","f":"Графічне","why":""},{"n":"пісня","f":"Звукове","why":""},{"n":"дзвінок будильника","f":"Звукове","why":""}],"stars":[1,6]},{"n":2,"task":"Що ми сприймаємо ОЧИМА? 👀","hint":"Познач лише те, що ми сприймаємо <b>очима</b> (зорова інформація).","type":"pick","items":[{"n":"веселка","ok":true,"why":""},{"n":"музика","ok":false,"why":"це слухова"},{"n":"картина","ok":true,"why":""},{"n":"аромат квітів","ok":false,"why":"це нюхова"},{"n":"світлофор","ok":true,"why":""},{"n":"смак яблука","ok":false,"why":"це смакова"},{"n":"текст у книзі","ok":true,"why":""},{"n":"спів пташки","ok":false,"why":"це слухова"}],"stars":[7,10]},{"n":3,"task":"Що це за процес?","hint":"Який <b>інформаційний процес</b> тут відбувається? Тисни кнопку.","type":"choice","items":[{"q":"Вчителька читає нам умову задачі","a":"Передавання"},{"q":"Записуємо відповідь у зошит","a":"Зберігання"},{"q":"Шукаємо потрібну статтю в Інтернеті","a":"Пошук"},{"q":"Рахуємо приклад і отримуємо результат","a":"Опрацювання"},{"q":"Зберігаємо фото на флешку","a":"Зберігання"}],"stars":[11,15]},{"n":4,"task":"Який це тип даних? 🧩","hint":"Останнє! Розклади дані за <b>типом</b>: числові, текстові чи графічні.","type":"sort","folders":["Числові","Текстові","Графічні"],"items":[{"n":"125","f":"Числові","why":""},{"n":"твій вік","f":"Числові","why":""},{"n":"ім''я «Оля»","f":"Текстові","why":""},{"n":"вірш","f":"Текстові","why":""},{"n":"фотографія","f":"Графічні","why":""},{"n":"схема","f":"Графічні","why":""}],"stars":[16,21]}]}'::jsonb, now()
