select 'grafika-6', '{"slug":"grafika-6","title":"Графіка: растр, вектор і свідомий вибір — гра для 6 класу","max":27,"stars":27,"rounds":[{"n":1,"type":"sort","task":"Який вид графіки доцільний для цієї задачі? 🎨","hint":"Згадай: <b>вектор</b> масштабується без утрати якості, <b>растр</b> передає реальність. Спершу торкнись картки, потім — папки.","folders":["Вектор","Растр"],"stars":[1,6],"items":[{"n":"Логотип школи на банер","f":"Вектор","why":""},{"n":"Піктограми застосунків","f":"Вектор","why":""},{"n":"Креслення деталі","f":"Вектор","why":""},{"n":"Фото класу","f":"Растр","why":""},{"n":"Репродукція картини","f":"Растр","why":""},{"n":"Скан сторінки зошита","f":"Растр","why":""}]},{"n":2,"type":"sort","task":"Чим краще зробити цей елемент? 🛠️","hint":"Головний раунд. <b>Крива Безьє</b> — для плавного; <b>примітив</b> — для геометричного; <b>копіювання</b> — для того, що повторюється.","folders":["Крива Безьє","Готовий примітив","Копіювання"],"stars":[7,12],"items":[{"n":"Плавне стебло квітки","f":"Крива Безьє","why":""},{"n":"Хвиля на морі","f":"Крива Безьє","why":""},{"n":"Прямокутне вікно будинку","f":"Готовий примітив","why":""},{"n":"Сонце — рівне коло","f":"Готовий примітив","why":""},{"n":"Вісім однакових пелюсток","f":"Копіювання","why":""},{"n":"Ряд однакових плиток орнаменту","f":"Копіювання","why":""}]},{"n":3,"type":"order","task":"Розстав кроки створення векторного зображення 1 → 5","hint":"Натискай кроки <b>в правильному порядку</b>. Пам''ятай, без якого кроку нічого не працює.","stars":[13,17],"items":[{"n":"Створити новий файл"},{"n":"Додати векторний шар"},{"n":"Намалювати об''єкти"},{"n":"Упорядкувати й згрупувати"},{"n":"Зберегти як SVG"}]},{"n":4,"type":"pick","task":"Познач те, що роблять ЗАСОБОМ програми, а не на око 🎯","hint":"Свідомо — це коли точність дає <b>програма</b>, а не рука з мишею.","stars":[18,21],"items":[{"n":"Вирівняти 5 квіток у ряд — Компонування","ok":true,"why":""},{"n":"Однакова відстань — Інтервал","ok":true,"why":""},{"n":"Два однакові прямокутники — числа в Геометрії","ok":true,"why":""},{"n":"Розподілити по вертикалі — Розподілити","ok":true,"why":""},{"n":"Підганяти мишею, доки не «схоже»","ok":false,"why":"це не точність, а здогад"},{"n":"Прикласти лінійку до екрана","ok":false,"why":"екран показує не справжній розмір"},{"n":"Копіювати й трохи посунути кожен","ok":false,"why":"відстані вийдуть різними"}]},{"n":5,"type":"sort","task":"У якому форматі це зберегти? 💾","hint":"Останній раунд. <b>SVG</b> — вектор; <b>PNG</b> — готовий результат; <b>KRA/PSD</b> — робочий файл із шарами.","folders":["SVG","PNG","KRA / PSD"],"stars":[22,27],"items":[{"n":"Логотип для друку на банері","f":"SVG","why":""},{"n":"Векторний малюнок для сайту","f":"SVG","why":""},{"n":"Готова робота для Classroom","f":"PNG","why":""},{"n":"Скріншот екрана з результатом","f":"PNG","why":""},{"n":"Файл, який ще будемо редагувати","f":"KRA / PSD","why":""},{"n":"Малюнок із кількома шарами","f":"KRA / PSD","why":""}]}]}'::jsonb, now()
