select 'koduvannya-8', '{"slug":"koduvannya-8","title":"Кодування даних: біти, байти й обчислення — гра для 8 класу","max":18,"stars":18,"rounds":[{"n":1,"type":"num","task":"Прочитай двійковий запис — запиши число в десятковій системі","hint":"Підпиши під одиницями їхні <b>ваги</b> (128 64 32 16 8 4 2 1) і <b>додай</b> лише ті, де стоїть 1.","items":[{"star":1,"q":"Яке десяткове число записано як <code>1011</code>?","a":11,"u":"","calc":"8 + 2 + 1 = 11","tip":"Ваги справа наліво: 1, 2, 4, 8. Додай ті, де стоїть одиниця.","trap":"13 — ваги підписали зліва направо (1, 2, 4, 8). Ваги йдуть справа наліво: одиниця стоїть праворуч."},{"star":2,"q":"Яке десяткове число записано як <code>10010</code>?","a":18,"u":"","calc":"16 + 2 = 18","tip":"Тут п’ять розрядів: ваги 16, 8, 4, 2, 1. Не забудь нуль у середині — він нічого не додає.","trap":"9 — ваги зліва направо. Правильно: 16 + 2."},{"star":3,"q":"Яке десяткове число записано байтом <code>00010100</code>?","a":20,"u":"","calc":"16 + 4 = 20","tip":"Провідні нулі нічого не змінюють. Дивись, під якими одиницями стоять ваги 16 і 4.","trap":"40 — ваги зліва направо. Провідні нулі нічого не додають."},{"star":4,"q":"Яке десяткове число записано байтом <code>01100100</code>?","a":100,"u":"","calc":"64 + 32 + 4 = 100","tip":"Ваги: 128 64 32 16 8 4 2 1. Одиниці стоять під 64, 32 і 4.","trap":"38 — ваги зліва направо. Правильно: 64 + 32 + 4."}]},{"n":2,"type":"pick","task":"Познач усі ПРАВИЛЬНІ пари «число — байт» 🔎","hint":"Правильних пар <b>чотири</b>. Пам’ятай: нулі дописують <b>зліва</b>, і в байті рівно вісім цифр.","stars":[5,8],"items":[{"n":"5 = 00000101","ok":true,"why":""},{"n":"13 = 00001101","ok":true,"why":""},{"n":"20 = 00010100","ok":true,"why":""},{"n":"63 = 00111111","ok":true,"why":""},{"n":"5 = 10100000","ok":false,"why":"нулі дописано праворуч, і це вже 160, а не 5"},{"n":"100 = 01100101","ok":false,"why":"64+32+4+1 = 101, а не 100"},{"n":"18 = 00011000","ok":false,"why":"16+8 = 24, а не 18"}]},{"n":3,"type":"num","task":"Переходи між одиницями — запиши лише число","hint":"До <b>менших</b> одиниць — множимо, до <b>більших</b> — ділимо. Біт↔байт — <b>8</b>, решта щаблів — <b>1024</b>.","items":[{"star":9,"q":"<code>5 Б</code> — це скільки бітів?","a":40,"u":"б","calc":"5 · 8 = 40","tip":"Байт → біт: множимо на 8, а не на 1024.","trap":"5120 — помножили на 1024. Байт → біт завжди ×8."},{"star":10,"q":"<code>4096 Б</code> — це скільки кілобайтів?","a":4,"u":"кБ","calc":"4096 : 1024 = 4","tip":"До більших одиниць — ділимо. На 1024.","trap":"32768 — помножили на 8 замість ділити на 1024."},{"star":11,"q":"<code>2 кБ</code> — це скільки байтів?","a":2048,"u":"Б","calc":"2 · 1024 = 2048","tip":"До менших одиниць — множимо на 1024. Не на 1000.","trap":"2000 — помножили на 1000. У нас 1 кБ = 1024 Б."},{"star":12,"q":"<code>10 кБ</code> — це скільки <b>бітів</b>?","a":81920,"u":"б","calc":"10 · 1024 = 10 240 Б → · 8 = 81 920","tip":"Тут ДВА щаблі: спершу кБ → Б (·1024), потім Б → б (·8).","trap":"10240 — зупинилися на байтах. Треба ще ×8, бо питають біти."},{"star":13,"q":"<code>3 МБ</code> — це скільки байтів?","a":3145728,"u":"Б","calc":"3 · 1024 = 3072 кБ → · 1024 = 3 145 728","tip":"Іди щаблями: МБ → кБ → Б. Обидва множники по 1024.","trap":"3072 — пройшли тільки один щабель (МБ → кБ). Потрібен ще один ×1024."}]},{"n":4,"type":"num","task":"Довжина двійкового коду тексту (кодування Windows-1251)","hint":"У Windows-1251 <b>один символ = один байт</b>. Пропуски й знаки — теж символи.","items":[{"star":14,"q":"Скільком <b>байтам</b> дорівнює код повідомлення <code>Біт і байт</code>?","a":10,"u":"Б","calc":"10 символів → 10 Б","tip":"Порахуй КОЖЕН знак, разом із пропусками. Їх тут два.","trap":"8 — не порахували два пропуски. Пропуск — теж символ."},{"star":15,"q":"А скільком <b>бітам</b> дорівнює код того самого повідомлення?","a":80,"u":"б","calc":"10 · 8 = 80","tip":"Байт → біт: множимо на 8.","trap":"10 — це відповідь на ПОПЕРЕДНЄ питання (байти). Тут питають біти: 10 · 8 = 80."},{"star":16,"q":"У рядку 60 символів, на сторінці 40 рядків, у тексті 20 сторінок. Скільком <b>байтам</b> дорівнює код тексту?","a":48000,"u":"Б","calc":"60 · 40 = 2400 → · 20 = 48 000","tip":"«Поверхи»: символ → рядок → сторінка → текст. Кожен крок — одне множення.","trap":"2400 — забули помножити на сторінки. 384000 — перевели в біти, а питають байти."}]},{"n":5,"type":"num","task":"Розмір файлу BMP — останній раунд","hint":"У 24-розрядному рисунку піксель — <b>3 байти</b>. Довжина рядка мусить бути <b>кратна 4</b>: залишок 1 → +3, залишок 2 → +2, залишок 3 → +1.","items":[{"star":17,"q":"24-розрядний BMP, ширина <b>25</b> пікселів. Скільком байтам дорівнює <b>один рядок із вирівнюванням</b>?","a":76,"u":"Б","calc":"75 + 1 = 76","tip":"25 · 3 = 75. Тепер: 75 = 4·18 + 3, отже залишок 3 → додати 1.","trap":"75 — без вирівнювання. 78 — додали 3 замість 1 (залишок 3 → +1)."},{"star":18,"q":"Той самий рисунок має висоту <b>20</b> пікселів. Який <b>розмір файлу</b> в байтах (заголовок — 54 Б)?","a":1574,"u":"Б","calc":"20 · 76 = 1520 → + 54 = 1574","tip":"Рядок із вирівнюванням — 76 Б. Помнож на кількість рядків і додай заголовок 54 Б.","trap":"1520 — забули заголовок 54 Б. 1554 — брали рядок 75 Б без вирівнювання."}]}]}'::jsonb, now()
where exists (select 1 from public.games where slug = 'koduvannya-8')
on conflict (slug) do update set data = excluded.data, updated_at = now();

