select 'metadani-9', '{"slug":"metadani-9","title":"Метадані файлу: слід, а не свідчення — гра для 9 класу","max":10,"stars":10,"rounds":[{"n":1,"task":"Файл .docx усередині влаштований не так, як здається. Три питання про те, що там насправді.","hint":"","type":"seq","items":[{"q":"Файл <code>.docx</code> за своєю будовою — це:","opts":[{"t":"ZIP-архів із кількох файлів","ok":true,"why":""},{"t":"один суцільний текстовий файл","ok":false,"why":""},{"t":"зображення сторінок документа","ok":false,"why":""},{"t":"база даних","ok":false,"why":""}]},{"q":"Разом із файлом <code>.docx</code> до іншої людини поїдуть <b>(познач усі правильні)</b>:","multi":true,"opts":[{"t":"ім''я автора й того, хто змінював документ останнім","ok":true,"why":""},{"t":"дати створення та останньої зміни","ok":true,"why":""},{"t":"коментарі й примітки, яких не видно в тексті","ok":true,"why":""},{"t":"пароль вашого акаунта","ok":false,"why":"пароль ніде в самому документі не зберігається"},{"t":"інші файли з вашого комп''ютера","ok":false,"why":"у файл потрапляють дані цього документа, а не диска"}]},{"q":"Ти завантажив з інтернету готовий шаблон резюме, змінив у ньому текст і надіслав. Що побачить одержувач у властивостях файла?","opts":[{"t":"ім''я того, хто зробив шаблон, — і твоє як того, хто змінював останнім","ok":true,"why":""},{"t":"тільки твоє ім''я","ok":false,"why":""},{"t":"нічого: після зміни тексту всі дані стираються","ok":false,"why":""},{"t":"назву сайту, з якого завантажено шаблон","ok":false,"why":""}]}],"stars":[1,3]},{"n":2,"task":"Про PDF існує міф. Перевіримо, що він захищає насправді.","hint":"","type":"seq","items":[{"q":"«Я зберіг документ у <code>PDF</code>, значить його не змінять і текст не витягнуть». Це:","opts":[{"t":"неправда: текст із PDF копіюється, PDF редагується, і метадані в ньому теж є","ok":true,"why":""},{"t":"правда: PDF захищений від будь-яких змін","ok":false,"why":""},{"t":"правда, якщо не ставити пароль","ok":false,"why":""},{"t":"правда для PDF, створеного з Word","ok":false,"why":""}]},{"q":"Що насправді захищає формат <code>PDF</code>?","opts":[{"t":"вигляд документа, а не його вміст","ok":true,"why":""},{"t":"вміст документа від копіювання","ok":false,"why":""},{"t":"документ від відкривання без пароля","ok":false,"why":""},{"t":"ім''я автора від сторонніх очей","ok":false,"why":""}]},{"q":"Чому для надсилання документа незнайомій людині все ж радять <code>PDF</code>?","opts":[{"t":"бо вигляд буде однаковий у всіх і бо PDF не несе з собою коментарів та правок","ok":true,"why":""},{"t":"бо PDF найменший за розміром","ok":false,"why":""},{"t":"бо PDF неможливо відкрити без спеціальної програми","ok":false,"why":""},{"t":"бо PDF не містить жодних метаданих","ok":false,"why":""}]}],"stars":[4,6]},{"n":3,"task":"Два питання про рішення, а не про кнопки.","hint":"","type":"seq","items":[{"q":"Чого з переліченого робити <b>не варто</b>?","opts":[{"t":"вставляти чужий документ (медичну довідку, лист, документи батьків) у безкоштовний онлайн-перекладач","ok":true,"why":""},{"t":"зберігати свій документ у PDF перед надсиланням","ok":false,"why":""},{"t":"перевіряти властивості файла, взятого з чужого шаблону","ok":false,"why":""},{"t":"видаляти примітки перед тим, як надіслати документ","ok":false,"why":""}]},{"q":"Ти диктував текст голосом у практичній роботі № 1. Куди йшов звук?","opts":[{"t":"на сервер, де його розпізнавали, — а не тільки у твій комп''ютер","ok":true,"why":""},{"t":"нікуди: усе відбувалося у твоєму комп''ютері","ok":false,"why":""},{"t":"у файл на твоєму диску, а потім видалявся","ok":false,"why":""},{"t":"у мікрофон і назад у навушники","ok":false,"why":""}]}],"stars":[7,8]},{"n":4,"task":"Останній раунд. Два найважчі питання роботи.","hint":"","type":"seq","items":[{"q":"Ти поставив своє <b>прізвище</b> в нижній колонтитул документа й виклав документ у відкритий чат класу. Що ти зробив?","opts":[{"t":"поставив своє прізвище на кожну сторінку документа й показав його всім, хто має доступ до чату","ok":true,"why":""},{"t":"нічого особливого: колонтитул усе одно не друкується","ok":false,"why":""},{"t":"захистив документ від того, щоб його присвоїли","ok":false,"why":""},{"t":"показав прізвище лише на першій сторінці","ok":false,"why":""}]},{"q":"У службових даних файла написано, що його створено в програмі <code>Microsoft Macintosh Word</code>, хоча насправді це не так. Правильний висновок:","opts":[{"t":"метадані — це слід, а не свідчення: вони можуть бути неточними або успадкованими від шаблону, тому за ними не можна нікого звинувачувати","ok":true,"why":""},{"t":"файл підроблено","ok":false,"why":""},{"t":"документ справді робили на Mac","ok":false,"why":""},{"t":"комп''ютер помилився, і файл треба видалити","ok":false,"why":""}]}],"stars":[9,10]}]}'::jsonb, now()
